import json
import sys

a = json.load(open(sys.argv[1]))
b = json.load(open(sys.argv[2]))
na, nb = sys.argv[3], sys.argv[4]
da = {}
for e in a:
    da.setdefault(e["key"], e["res"])
db = {}
for e in b:
    db.setdefault(e["key"], e["res"])
keys = list(da.keys())
diffs = 0
groups = {}
for k in keys:
    if k not in db:
        print("MISSING in", nb, k)
        continue
    if da[k] != db[k]:
        diffs += 1
        fn = k.split("|")[0]
        groups.setdefault(fn, []).append((k, da[k], db[k]))
print(f"total keys={len(keys)} diffs={diffs}")
for fn, items in sorted(groups.items()):
    print(f"\n### {fn}: {len(items)} diffs")
    for k, x, y in items[:60]:
        print(f"  {k}\n     {na}: {x}\n     {nb}: {y}")
    if len(items) > 60:
        print(f"  ... {len(items)-60} more")

